package io.github.diodeme.ji.testkit;

import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;

/** Finite ID source that fails instead of inventing nondeterministic values. */
public final class FixedIdGenerator {
    private final Deque<String> values;

    public FixedIdGenerator(Collection<String> values) {
        this.values = new ArrayDeque<>(values);
    }

    public synchronized String next() {
        String value = values.pollFirst();
        if (value == null) {
            throw new IllegalStateException("fixed ID sequence exhausted");
        }
        return value;
    }
}
